<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=post('type');if(post('action')==='delete'&&$type){try{$pdo->prepare('DELETE FROM room_type WHERE room_type=?')->execute([$type]);flash('success','Room type deleted.');}catch(Throwable $e){flash('error','Room type cannot be deleted while rooms use it.');}}redirect('room_types.php');}
$rows=$pdo->query('SELECT * FROM room_type ORDER BY room_type')->fetchAll();page_header('Room Types','room_type');?>
<div class="page-head"><h1>Room Types</h1><a class="btn primary" href="room_type_form.php">Add Room Type</a></div><section class="card table-wrap"><table><thead><tr><th>Type</th><th>Price</th><th>Details</th><th>Quantity</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['room_type'])?></td><td><?=money($r['room_price'])?></td><td><?=e($r['room_details'])?></td><td><?=$r['room_quantity']?></td><td class="actions"><a href="room_type_form.php?id=<?=urlencode($r['room_type'])?>">Edit</a><form method="post" onsubmit="return confirm('Are you sure?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="type" value="<?=e($r['room_type'])?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?></tbody></table></section><?php page_footer();?>
